python3 << 'PYEOF'
import json, requests

API_KEY = "key_[REDACTED]"
LLM_ID = "llm_44111168b1a2a469f50891b26e34"

with open("/tmp/cnkb_prompt_modified.txt") as f:
    new_prompt = f.read()

r = requests.patch(
    f"https://api.retellai.com/update-retell-llm/{LLM_ID}",
    headers={
        "Authorization": f"Bearer {API_KEY}",
        "Content-Type": "application/json"
    },
    json={"general_prompt": new_prompt}
)

print(f"Status: {r.status_code}")
if r.status_code == 200:
    resp = r.json()
    print(f"Version: {resp.get('version')}")
    print(f"LLM ID: {resp.get('llm_id')}")
    # Verify the new stage 1 is in the prompt
    returned_prompt = resp.get("general_prompt", "")
    if "## Stage 1: Program Qualifier" in returned_prompt:
        print("✅ Program Qualifier stage confirmed in deployed prompt")
    else:
        print("❌ Program Qualifier NOT found in deployed prompt")
    if "## Stage 2: Address Initial Questions" in returned_prompt:
        print("✅ Stage 2 (Questions) confirmed")
    if "## Stage 6: Close the Call" in returned_prompt:
        print("✅ Stage 6 (Close) confirmed — all 6 stages present")
else:
    print(f"Error: {r.text}")
PYEOF

