   1→/**
   2→ * Visual Workload Tracer Dashboard
   3→ *
   4→ * n8n-style execution trace viewer served from the worker.
   5→ * Shows recent executions and allows drilling into span details.
   6→ */
   7→
   8→import type { Env } from '../lib/types';
   9→import { createClient } from '@supabase/supabase-js';
  10→
  11→/**
  12→ * Handle dashboard requests
  13→ */
  14→export async function handleDashboard(request: Request, env: Env): Promise<Response> {
  15→  const url = new URL(request.url);
  16→  const traceId = url.searchParams.get('trace');
  17→
  18→  // If trace_id provided, fetch that trace's spans
  19→  let traceData = null;
  20→  if (traceId) {
  21→    const client = createClient(env.SUPABASE_URL, env.SUPABASE_SERVICE_KEY);
  22→    const { data } = await client.rpc('get_trace', { p_trace_id: traceId });
  23→    traceData = data;
  24→  }
  25→
  26→  return new Response(getDashboardHTML(env, traceId, traceData), {
  27→    headers: { 'Content-Type': 'text/html; charset=utf-8' },
  28→  });
  29→}
  30→
  31→/**
  32→ * API endpoint for fetching recent executions (AJAX)
  33→ */
  34→export async function handleDashboardAPI(request: Request, env: Env): Promise<Response> {
  35→  const url = new URL(request.url);
  36→  const action = url.searchParams.get('action');
  37→
  38→  const client = createClient(env.SUPABASE_URL, env.SUPABASE_SERVICE_KEY);
  39→
  40→  if (action === 'recent') {
  41→    const { data, error } = await client
  42→      .from('recent_executions')
  43→      .select('*')
  44→      .limit(50);
  45→
  46→    if (error) {
  47→      return new Response(JSON.stringify({ error: error.message }), {
  48→        status: 500,
  49→        headers: { 'Content-Type': 'application/json' },
  50→      });
  51→    }
  52→
  53→    return new Response(JSON.stringify(data), {
  54→      headers: { 'Content-Type': 'application/json' },
  55→    });
  56→  }
  57→
  58→  if (action === 'trace') {
  59→    const traceId = url.searchParams.get('id');
  60→    if (!traceId) {
  61→      return new Response(JSON.stringify({ error: 'Missing trace id' }), {
  62→        status: 400,
  63→        headers: { 'Content-Type': 'application/json' },
  64→      });
  65→    }
  66→
  67→    const { data, error } = await client.rpc('get_trace', { p_trace_id: traceId });
  68→
  69→    if (error) {
  70→      return new Response(JSON.stringify({ error: error.message }), {
  71→        status: 500,
  72→        headers: { 'Content-Type': 'application/json' },
  73→      });
  74→    }
  75→
  76→    return new Response(JSON.stringify(data), {
  77→      headers: { 'Content-Type': 'application/json' },
  78→    });
  79→  }
  80→
  81→  if (action === 'leads') {
  82→    const { data, error } = await client
  83→      .from('leads')
  84→      .select('id, centre_id, first_name, last_name, phone, email, program_interest, status, attempt_count, last_outcome, appointment_booked, campaign_type, batch_id, created_at, updated_at')
  85→      .order('updated_at', { ascending: false })
  86→      .limit(200);
  87→
  88→    if (error) {
  89→      return new Response(JSON.stringify({ error: error.message }), {
  90→        status: 500,
  91→        headers: { 'Content-Type': 'application/json' },
  92→      });
  93→    }
  94→
  95→    return new Response(JSON.stringify(data), {
  96→      headers: { 'Content-Type': 'application/json' },
  97→    });
  98→  }
  99→
 100→  if (action === 'lead-detail') {
 101→    const leadId = url.searchParams.get('id');
 102→    if (!leadId) {
 103→      return new Response(JSON.stringify({ error: 'Missing lead id' }), {
 104→        status: 400,
 105→        headers: { 'Content-Type': 'application/json' },
 106→      });
 107→    }
 108→
 109→    const { data: lead, error: leadError } = await client
 110→      .from('leads')
 111→      .select('*')
 112→      .eq('id', leadId)
 113→      .single();
 114→
 115→    if (leadError) {
 116→      return new Response(JSON.stringify({ error: leadError.message }), {
 117→        status: 500,
 118→        headers: { 'Content-Type': 'application/json' },
 119→      });
 120→    }
 121→
 122→    const { data: attempts, error: attemptsError } = await client
 123→      .from('call_attempts')
 124→      .select('*')
 125→      .eq('lead_id', leadId)
 126→      .order('started_at', { ascending: false });
 127→
 128→    if (attemptsError) {
 129→      return new Response(JSON.stringify({ error: attemptsError.message }), {
 130→        status: 500,
 131→        headers: { 'Content-Type': 'application/json' },
 132→      });
 133→    }
 134→
 135→    return new Response(JSON.stringify({ lead, attempts }), {
 136→      headers: { 'Content-Type': 'application/json' },
 137→    });
 138→  }
 139→
 140→  if (action === 'db-stats') {
 141→    const [leads, attempts, centres, analytics] = await Promise.all([
 142→      client.from('leads').select('id, status', { count: 'exact', head: false }),
 143→      client.from('call_attempts').select('id, outcome', { count: 'exact', head: false }),
 144→      client.from('centres').select('id', { count: 'exact', head: false }),
