 146→    ]);
 147→
 148→    const statusCounts: Record<string, number> = {};
 149→    (leads.data || []).forEach((l: { status: string }) => {
 150→      statusCounts[l.status] = (statusCounts[l.status] || 0) + 1;
 151→    });
 152→
 153→    const outcomeCounts: Record<string, number> = {};
 154→    (attempts.data || []).forEach((a: { outcome: string }) => {
 155→      if (a.outcome) outcomeCounts[a.outcome] = (outcomeCounts[a.outcome] || 0) + 1;
 156→    });
 157→
 158→    return new Response(JSON.stringify({
 159→      tables: {
 160→        leads: { count: leads.count || (leads.data || []).length, statusCounts },
 161→        call_attempts: { count: attempts.count || (attempts.data || []).length, outcomeCounts },
 162→        centres: { count: centres.count || (centres.data || []).length },
 163→        call_analytics: { count: analytics.count || (analytics.data || []).length },
 164→        execution_traces: { count: '(view)' },
 165→      },
 166→    }), {
 167→      headers: { 'Content-Type': 'application/json' },
 168→    });
 169→  }
 170→
 171→  return new Response(JSON.stringify({ error: 'Unknown action' }), {
 172→    status: 400,
 173→    headers: { 'Content-Type': 'application/json' },
 174→  });
 175→}
