 518→    /* ── Helpers ── */
 519→    function fmtDur(ms) {
 520→      if (!ms && ms !== 0) return '-';
 521→      if (ms < 1000) return ms + 'ms';
 522→      return (ms / 1000).toFixed(1) + 's';
 523→    }
 524→    function fmtTime(ts) {
 525→      if (!ts) return '-';
