 591→      if (!executions.length) {
 592→        el.innerHTML = '<div class="text-gray-600 text-center py-8 text-sm">No executions</div>';
 593→        return;
 594→      }
 595→      el.innerHTML = executions.map(function(ex) {
 596→        const sel = selectedTraceId === ex.trace_id;
 597→        const st = ex.status;
 598→        const stColor = st === 'success' ? 'bg-green-500/20 text-green-400' : st === 'error' ? 'bg-red-500/20 text-red-400' : st === 'running' ? 'bg-yellow-500/20 text-yellow-400' : 'bg-gray-500/20 text-gray-400';
 599→        return '<div class="p-2.5 rounded-lg cursor-pointer transition-all ' + (sel ? 'bg-blue-950 border border-blue-500/50' : 'hover:bg-gray-800/80 border border-transparent') + '" onclick="selectTrace(\\'' + ex.trace_id + '\\')">'
 600→          + '<div class="flex items-center justify-between mb-1">'
 601→          + '<span class="exec-badge ' + stColor + '">' + (ex.trigger_type || 'unknown') + '</span>'
 602→          + '<span class="text-xs text-gray-500">' + fmtDur(ex.duration_ms) + '</span>'
 603→          + '</div>'
 604→          + '<div class="text-xs text-gray-500">' + fmtDate(ex.started_at) + '</div>'
 605→          + '<div class="text-xs text-gray-600 mt-0.5">' + (ex.span_count || 0) + ' nodes' + (ex.error_count > 0 ? ' \\u00B7 <span class="text-red-400">' + ex.error_count + ' err</span>' : '') + '</div>'
 606→          + '</div>';
