 618→    /* ── Layout algorithm: tree positions ── */
 619→    function layoutTree(spans) {
 620→      var map = {};
 621→      spans.forEach(function(s) { map[s.span_id] = Object.assign({}, s, { children: [], _x: 0, _y: 0 }); });
 622→
 623→      var roots = [];
 624→      spans.forEach(function(s) {
 625→        if (s.parent_span_id && map[s.parent_span_id]) {
 626→          map[s.parent_span_id].children.push(map[s.span_id]);
 627→        } else {
 628→          roots.push(map[s.span_id]);
 629→        }
 630→      });
 631→
 632→      // Sort children by started_at
 633→      Object.values(map).forEach(function(n) {
 634→        n.children.sort(function(a, b) { return new Date(a.started_at) - new Date(b.started_at); });
 635→      });
 636→
 637→      var NODE_W = 180;
 638→      var NODE_H = 68;
 639→      var GAP_X = 70;
 640→      var GAP_Y = 20;
 641→      var COLS = [];
 642→
 643→      // Assign columns (depth) and compute subtree heights
 644→      function measure(node, depth) {
 645→        if (!COLS[depth]) COLS[depth] = [];
 646→        COLS[depth].push(node);
 647→        node._depth = depth;
 648→
 649→        if (node.children.length === 0) {
 650→          node._subtreeH = NODE_H;
 651→          return NODE_H;
 652→        }
 653→        var totalH = 0;
 654→        node.children.forEach(function(ch, i) {
 655→          if (i > 0) totalH += GAP_Y;
 656→          totalH += measure(ch, depth + 1);
 657→        });
 658→        node._subtreeH = Math.max(NODE_H, totalH);
 659→        return node._subtreeH;
 660→      }
 661→
 662→      var totalRootH = 0;
 663→      roots.forEach(function(r, i) {
 664→        if (i > 0) totalRootH += GAP_Y;
 665→        totalRootH += measure(r, 0);
 666→      });
 667→
 668→      // Position nodes
 669→      function position(node, x, yStart) {
 670→        node._x = x;
 671→        node._y = yStart + (node._subtreeH - NODE_H) / 2;
 672→
 673→        var childY = yStart;
 674→        node.children.forEach(function(ch, i) {
 675→          if (i > 0) childY += GAP_Y;
 676→          position(ch, x + NODE_W + GAP_X, childY);
 677→          childY += ch._subtreeH;
 678→        });
 679→      }
 680→
 681→      var rootY = 20;
 682→      roots.forEach(function(r, i) {
 683→        if (i > 0) rootY += GAP_Y;
 684→        position(r, 20, rootY);
 685→        rootY += r._subtreeH;
 686→      });
 687→
 688→      // Collect all nodes and edges
 689→      var nodes = Object.values(map);
 690→      var edges = [];
 691→      nodes.forEach(function(n) {
 692→        n.children.forEach(function(ch) {
 693→          edges.push({ from: n, to: ch });
 694→        });
 695→      });
 696→
 697→      // Canvas size
 698→      var maxX = Math.max.apply(null, nodes.map(function(n) { return n._x; })) + NODE_W + 40;
 699→      var maxY = Math.max.apply(null, nodes.map(function(n) { return n._y; })) + NODE_H + 40;
 700→
 701→      return { nodes: nodes, edges: edges, roots: roots, width: maxX, height: maxY, NODE_W: NODE_W, NODE_H: NODE_H };
 702→    }
