 713→
 714→      var layout = layoutTree(spans);
 715→      var nodes = layout.nodes;
 716→      var edges = layout.edges;
 717→      var width = layout.width;
 718→      var height = layout.height;
 719→      var NODE_W = layout.NODE_W;
 720→      var NODE_H = layout.NODE_H;
 721→
 722→      // Build SVG arrows
 723→      var svgArrows = '';
 724→      edges.forEach(function(e) {
 725→        var x1 = e.from._x + NODE_W;
 726→        var y1 = e.from._y + NODE_H / 2;
 727→        var x2 = e.to._x;
