 731→        var color = e.to.status === 'error' ? '#ef4444' : e.to.status === 'running' ? '#eab308' : '#475569';
 732→        svgArrows += '<path d="M' + x1 + ',' + y1 + ' C' + cx1 + ',' + y1 + ' ' + cx2 + ',' + y2 + ' ' + x2 + ',' + y2 + '" fill="none" stroke="' + color + '" stroke-width="2" class="arrow-path"/>'
 733→          + '<circle cx="' + x2 + '" cy="' + y2 + '" r="3" fill="' + color + '"/>';
 734→      });
 735→
 736→      // Build node cards
 737→      var nodeCards = '';
 738→      nodes.forEach(function(n) {
