 752→          + '<span class="wf-node-status ' + stCls + '"></span>'
 753→          + '</div></div>';
 754→      });
 755→
 756→      container.innerHTML = '<div class="wf-canvas" style="width:' + width + 'px;height:' + height + 'px;">'
