 9→// Cache for agent versions (per agent, refreshed periodically)
10→const agentVersionCache = new Map<string, { version: number; time: number }>();
11→const VERSION_CACHE_TTL = 60000; // 1 minute
12→
13→/**
14→ * Gets the latest agent version (for using unpublished changes)
15→ */
16→async function getLatestAgentVersion(env: Env, agentId: string): Promise<number | undefined> {
17→  const now = Date.now();
18→  const cached = agentVersionCache.get(agentId);
19→  if (cached && (now - cached.time) < VERSION_CACHE_TTL) {
20→    return cached.version;
21→  }
22→
23→  try {
24→    const response = await fetch(`https://api.retellai.com/get-agent/${agentId}`, {
25→      headers: { Authorization: `Bearer ${env.RETELL_API_KEY}` },
26→    });
27→
28→    if (response.ok) {
29→      const agent = await response.json() as { version?: number };
30→      if (agent.version) {
31→        agentVersionCache.set(agentId, { version: agent.version, time: now });
32→        return agent.version;
33→      }
34→    }
35→  } catch (error) {
36→    console.warn(`Failed to fetch agent version for ${agentId}:`, error);
37→  }
38→
39→  return undefined;
40→}
